alter table public.profiles add column if not exists cls text not null default 'Mago';
alter table public.profiles add column if not exists avatar int not null default 0;
alter table public.profiles drop constraint if exists profiles_cls_chk;
alter table public.profiles add constraint profiles_cls_chk check (cls in ('Guerreiro','Mago','Ladino','Arqueiro','Clérigo','Bardo'));
alter table public.profiles drop constraint if exists profiles_avatar_chk;
alter table public.profiles add constraint profiles_avatar_chk check (avatar between 0 and 4);
grant update (name, bio, fac, data, cls, avatar) on public.profiles to authenticated;
create table if not exists public.event_joins (user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, ekey text not null, joined_at timestamptz not null default now(), primary key (user_id, ekey));
alter table public.event_joins enable row level security;
drop policy if exists "eventos: ler os meus" on public.event_joins;
create policy "eventos: ler os meus" on public.event_joins for select to authenticated using (user_id = auth.uid());
revoke insert, update, delete on public.event_joins from anon, authenticated;
create or replace function public.grant_xp(u uuid, x int, g int, capped boolean) returns void language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; td date := (now() at time zone 'utc')::date; ups int := 0; begin select * into p from profiles where id = u for update; if not found then return; end if; if p.day <> td then p.day := td; p.xp_day := 0; end if; if capped then x := least(x, greatest(150 - p.xp_day, 0)); if x = 0 then return; end if; p.xp_day := p.xp_day + x; end if; p.xp := p.xp + x; p.gold := p.gold + g; while p.xp >= p.level * 100 loop p.xp := p.xp - p.level * 100; p.level := p.level + 1; ups := ups + 1; end loop; update profiles set xp = p.xp, gold = p.gold, level = p.level, xp_day = p.xp_day, day = p.day, inv = inv || coalesce((select jsonb_agg(jsonb_build_object('id', gen_random_uuid()::text, 'k', 'chest', 'n', 'Baú do Aventureiro')) from generate_series(1, ups)), '[]'::jsonb) where id = u; end $$;
revoke execute on function public.grant_xp(uuid, int, int, boolean) from public, anon, authenticated;
create or replace function public.shop_buy(item text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; ids text[] := array['potion','chest','star','heart','diamond','ring','sword']; nm text[] := array['Poção de Vida','Baú do Aventureiro','Estrela da Sorte','Coração Vivo','Diamante Azul','Anel Sombrio','Espada Rúnica']; pr int[] := array[40,120,150,60,200,300,500]; ix int := array_position(ids, item); begin if ix is null then raise exception 'item inválido'; end if; perform me(); select * into p from profiles where id = auth.uid() for update; if jsonb_array_length(p.inv) >= 60 then raise exception 'inventário cheio'; end if; if p.gold < pr[ix] then raise exception 'ouro insuficiente'; end if; update profiles set gold = gold - pr[ix], inv = inv || jsonb_build_object('id', gen_random_uuid()::text, 'k', item, 'n', nm[ix]) where id = p.id; return me(); end $$;
create or replace function public.shop_use(iid text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; it jsonb; ix int := 0; fx int; k text; g int := 0; x int := 0; msg text; begin perform me(); select * into p from profiles where id = auth.uid() for update; for it in select * from jsonb_array_elements(p.inv) loop if it->>'id' = iid then fx := ix; k := it->>'k'; exit; end if; ix := ix + 1; end loop; if fx is null then raise exception 'item não encontrado'; end if; if k = 'potion' then x := 20; msg := 'Você usou a poção: +20 XP'; elsif k = 'star' then x := 50; msg := 'A estrela brilha: +50 XP'; elsif k = 'chest' then g := 50 + floor(random() * 150)::int; x := 30; msg := 'O baú tinha ' || g || ' de ouro e 30 XP!'; else raise exception 'este item é de coleção'; end if; update profiles set inv = inv - fx where id = p.id; perform grant_xp(p.id, x, g, false); return jsonb_build_object('msg', msg); end $$;
create or replace function public.daily_claim() returns jsonb language plpgsql security definer set search_path = public as $$ declare p profiles%rowtype; begin perform me(); select * into p from profiles where id = auth.uid() for update; if p.quests->>'daily' = '1' then raise exception 'recompensa já resgatada hoje'; end if; update profiles set quests = jsonb_set(quests, '{daily}', '"1"') where id = p.id; perform grant_xp(p.id, 0, 40, false); return me(); end $$;
create or replace function public.join_event(eid text) returns jsonb language plpgsql security definer set search_path = public as $$ declare len int; rg numeric; ek text; g int; x int; begin len := case eid when 'noite' then 1 when 'caca' then 3 when 'torneio' then 7 else null end; if len is null then raise exception 'evento inválido'; end if; perform me(); rg := floor(extract(epoch from now()) / (len * 86400)); ek := eid || ':' || rg::bigint; begin insert into event_joins (user_id, ekey) values (auth.uid(), ek); exception when unique_violation then raise exception 'você já participa deste evento'; end; g := case eid when 'noite' then 100 when 'torneio' then 250 else 0 end; x := case eid when 'noite' then 80 when 'caca' then 60 else 120 end; if eid = 'caca' then update profiles set inv = inv || jsonb_build_object('id', gen_random_uuid()::text, 'k', 'chest', 'n', 'Baú do Aventureiro') where id = auth.uid(); end if; perform grant_xp(auth.uid(), x, g, false); return me(); end $$;
